using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerToolType]
public sealed class ApiTools
{
    [McpServerTool, Description("Fetches a post by ID from the external API.")]
    public static async Task<string> GetPost(
        IHttpClientFactory httpClientFactory,
        [Description("The numeric ID of the post to retrieve.")] int id)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");

        var post = await client.GetFromJsonAsync<JsonElement>($"posts/{id}");
        return post.ToString();
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerPromptType]
public sealed class SummarizePrompts
{
    [McpServerPrompt, Description("Generates a prompt that asks for a concise summary of the provided text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Maximum number of sentences in the summary.")] int maxSentences = 3)
    {
        return
        [
            new(Role.User,
                $"Summarize the following text in at most {maxSentences} sentences. " +
                $"Be concise and capture the key points.\n\n{text}")
        ];
    }
}

